package com.mia.app.data.android.repo

import com.mia.app.domain.model.FundamentalsSnapshot
import com.mia.app.domain.model.Ratios
import java.time.LocalDate

/**
 * The fundamentals view of one symbol, with the freshness plan.md §10 demands.
 *
 * [stalenessLine] is generated by `com.mia.app.domain.ratios.FreshnessPolicy.describe`, so the
 * wording is the shared one and cannot drift from the policy that produced the state.
 * *"A stale P/E shown as live is the fastest way to lose trust"* (plan.md §10) is why this is a
 * required field on the type rather than something the screen assembles.
 */
data class FundamentalsView(
    val snapshot: FundamentalsSnapshot,
    /** `SINGLE` / `AGREED` / `CONFLICT` / `STALE`, already adjusted for freshness. */
    val ratios: Ratios,
    /** e.g. `as of 02 Oct 2026 (214 days old, older than the 200-day window …)`. */
    val stalenessLine: String,
    /** False when any section was missing — the UI must say so instead of showing four of six. */
    val complete: Boolean,
    /** Why it is not complete, one line per missing section. */
    val incompletenessNotes: List<String>,
)

/**
 * The only way `:app` reaches fundamentals.
 *
 * ### Why nothing here fetches implicitly
 * plan.md §3.6 makes screener.in the most request-sensitive source in the app (one URL shape,
 * no search, no pagination) and plan.md §13's mitigation is CGNAT awareness. A repository that
 * refreshed on every screen entry would undo both. So [snapshot] reads cache first and only
 * refetches when [maxAgeDays] has elapsed, and [refresh] is the explicit, user-initiated path.
 */
interface FundamentalsRepository {

    /**
     * The cached fundamentals page for `symbol`, refreshed only if the cache is older than
     * [maxAgeDays].
     *
     * `maxAgeDays` defaults to plan.md's own `FreshnessKind.FUNDAMENTALS_SNAPSHOT` window (7
     * days) because a screener.in page has no publication stamp: it changes when the company
     * files, so a week covers a normal refresh and still catches a forgotten one. Pass
     * `allowFetch = false` for a screen that must never touch the network — a share-brief image,
     * for instance, which renders whatever is cached and labels its age.
     */
    suspend fun snapshot(
        symbol: String,
        maxAgeDays: Long = DEFAULT_MAX_AGE_DAYS,
        allowFetch: Boolean = true,
    ): DataResult<FundamentalsView>

    /**
     * Fetches the page now and replaces the cache for `symbol`. The manual-refresh path.
     *
     * A failed parse is **not** written: an older, complete page is a better answer than a
     * freshly failed one, and plan.md §10's whole point is that a stale figure must be *labelled*
     * stale rather than replaced by nothing.
     */
    suspend fun refresh(symbol: String): DataResult<FundamentalsView>

    /** The merged ratios alone, for a screen that only needs the headline numbers. */
    suspend fun ratios(symbol: String): DataResult<Ratios>

    /** The most recent `asOf` this device holds for `symbol`, or `null` when it holds none. */
    suspend fun asOf(symbol: String): LocalDate?

    /** True when this device holds a fundamentals page for `symbol`. Never blocks on IO. */
    suspend fun hasCache(symbol: String): Boolean

    companion object {
        /**
         * plan.md §10 / `FreshnessKind.FUNDAMENTALS_SNAPSHOT`: the fundamentals window.
         * Restated here so the repository's cache policy reads in the same units as the policy
         * that judges it.
         */
        const val DEFAULT_MAX_AGE_DAYS: Long = 7L
    }
}